# Parse the notes into structured data
import re

parsed = []
for note in notes_content:
    title = note['title']
    m = re.search(r'(\d{4}-\d{2}-\d{2})', title)
    date = m.group(1)
    content = note['content']
    lines = content.split('\n')
    # Skip first line (header) and any empty lines
    habits = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if ':' in line:
            key, val = line.split(':', 1)
            habits[key.strip()] = val.strip()
    parsed.append({'date': date, 'habits': habits})

# Verify all notes have same habit keys in same order
first_habits = list(parsed[0]['habits'].keys())
for p in parsed:
    if list(p['habits'].keys()) != first_habits:
        print("Mismatch in habit order for", p['date'])
        break
else:
    print("All notes have same habit order:", first_habits)

# Print first few to confirm
for p in parsed[:3]:
    print(p['date'], p['habits'])

